ion_name": "湖南至中原", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "91dcc436-d86c-537f-af46-f8cb94441d52"}, {"title": "楚六军副使王环在石首击败荆南军", "start_year": 929, "end_year": 929, "time_original": "929年四月丙午", "dynasty": "五代十国", "description": "楚六军副使王环在石首击败荆南军。", "phases": [], "location_name": "石首", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "f9cfe94d-aa4d-516e-ac7d-637ee201bc9b"}, {"title": "朝廷首次令边境置马市，购买党项马，不许其直接赴阙", "start_year": 929, "end_year": 929, "time_original": "929年四月本段；确日未载", "dynasty": "五代十国", "description": "朝廷首次令边境置马市，购买党项马，不许其直接赴阙。", "phases": [], "location_name": "后唐边境", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "3882729e-0945-5c45-be44-23bd4a761e23"}, {"title": "此前党项赴阙以贡马为名，朝廷按价酬付并给予馆食、赏赐", "start_year": null, "end_year": null, "time_original": "先是：四月置马市政策之前，始年日未独载", "dynasty": "五代十国", "description": "此前党项赴阙以贡马为名，朝廷按价酬付并给予馆食、赏赐。", "phases": [], "location_name": "党项至阙下", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "e45d8115-3d30-50ed-a3f8-dc27c82ad84b"}, {"title": "主书记上述赴阙买马接待旧制每年花费五十余万缗", "start_year": null, "end_year": null, "time_original": "先是旧制度的年度开支概数；具体预算年度未独载", "dynasty": "五代十国", "description": "主书记上述赴阙买马接待旧制每年花费五十余万缗。", "phases": [], "location_name": "后唐财政", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "6f9131f5-c425-514a-a846-f176cddc8540"}, {"title": "有司以旧制费用耗蠹为苦，故停止直接赴阙买马方式", "start_year": 929, "end_year": 929, "time_original": "929年四月本段；确日未载", "dynasty": "五代十国", "description": "有司以旧制费用耗蠹为苦，故停止直接赴阙买马方式。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "627ca2a6-ce5a-5d3c-ad22-12755b265d68"}, {"title": "李从荣任河南尹、判六军诸卫事", "start_year": 929, "end_year": 929, "time_original": "929年四月壬子", "dynasty": "五代十国", "description": "李从荣任河南尹、判六军诸卫事。", "phases": [], "location_name": "河南府", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "71d43fac-bfa3-535c-9fa8-792a5897f53f"}, {"title": "李从厚任河东节度使、北都留守", "start_year": 929, "end_year": 929, "time_original": "929年四月壬子", "dynasty": "五代十国", "description": "李从厚任河东节度使、北都留守。", "phases": [], "location_name": "河东、北都", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "762958bd-982d-5012-a6c0-fd6358eba7a6"}, {"title": "契丹侵扰云州", "start_year": 929, "end_year": 929, "time_original": "929年四月本段；确日未载", "dynasty": "五代十国", "description": "契丹侵扰云州。", "phases": [], "location_name": "云州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "b33fa658-5ef4-5d49-b913-417a904e342d"}, {"title": "旧明宗纪补契丹遣捺括梅里等来朝贡，称取秃馁等骸骨", "start_year": 929, "end_year": 929, "time_original": "929年四月癸丑", "dynasty": "五代十国", "description": "旧明宗纪补契丹遣捺括梅里等来朝贡，称取秃馁等骸骨。", "phases": [], "location_name": "后唐朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "4166327c-2740-5220-b240-da0798949a3f"}, {"title": "旧明宗纪记捺括梅里等契丹使被斩于北市", "start_year": 929, "end_year": 929, "time_original": "929年四月癸丑", "dynasty": "五代十国", "des