SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "马殷命马希声知政事，总录内外军事。", "citation": "卷276·天成四年（929）·zztj-v276-y0929-p009·原文件第95行", "note": "原文：楚王殷命其子武安节度副使、判长沙府希声知政事，总录内外诸军事，；核对说明：知政和总军不是继王位，马殷仍在，未提前其卒与希声继立。", "status": "draft", "id": "e8129e47-707f-58de-b330-d60ba8aaf244", "subject_id": "5c02d4f4-84ef-5733-acff-a66d703e353b", "source_id": "85e0f53d-9359-534d-9333-821db7c28b85"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "929年三月本段；确日未载", "citation": "卷276·天成四年（929）·zztj-v276-y0929-p009·原文件第95行", "note": "原文：楚王殷命其子武安节度副使、判长沙府希声知政事，总录内外诸军事，；核对说明：按主书及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "2f336bca-f84d-519c-a8a7-2033fc6b2c48", "subject_id": "5c02d4f4-84ef-5733-acff-a66d703e353b", "source_id": "85e0f53d-9359-534d-9333-821db7c28b85"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记马殷：楚王、委子知政者。", "citation": "卷276·天成四年（929）·zztj-v276-y0929-p009·原文件第95行", "note": "原文：楚王殷命其子武安节度副使、判长沙府希声知政事，总录内外诸军事，；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "0ea564e4-8e97-5775-94b6-672cd943aa86", "subject_id": "7115610f-10b4-5211-b4a5-d2d089e6db83", "source_id": "85e0f53d-9359-534d-9333-821db7c28b85"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "马殷：楚王、委子知政者。", "citation": "卷276·天成四年（929）·zztj-v276-y0929-p009·原文件第95行", "note": "原文：楚王殷命其子武安节度副使、判长沙府希声知政事，总录内外诸军事，；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "3572f62f-bbba-5026-86a3-3c57f8351137", "subject_id": "9c8fb949-5fa8-51aa-b273-d89f22504738", "source_id": "85e0f53d-9359-534d-9333-821db7c28b85"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记马希声：武安节度副使判长沙府、获委知政总军者。", "citation": "卷276·天成四年（929）·zztj-v276-y0929-p009·原文件第95行", "note": "原文：楚王殷命其子武安节度副使、判长沙府希声知政事，总录内外诸军事，；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "377f7ca4-449b-5533-9166-947ef874c101", "subject_id": "5dca3ac0-5512-58ab-a330-ff34cb75ede8", "source_id": "85e0f53d-9359-534d-9333-821db7c28b85"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "马希声：武安节度副使判长沙府、获委知政总军者。", "citation": "卷276·天成四年（929）·zztj-v276-y0929-p009·原文件第95行", "note": "原文：楚王殷命其子武安节度副使、判长沙府希声知政事，总录内外诸军事，；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "bbd8b498-04ea-58bd-91ce-11daeb208fbf", "subject_id": "5c1dd9fd-b790-507d-b3b9-9547be07a116", "source_id": "85e0f53d-9359-534d-9333-821db7c28b85"}, {"subject_table": "person_relationship", "field_path": "description", "claim_text": "马殷是马希声的父亲。", "citation": "卷276·天成四年（929）·zztj-v276-y0929-p009·原文件第95行", "note": "原文：楚王殷命其子武安节度副使、判长沙府希声知政事，总录内外诸军事，；核对说明：原其子希声明父关系，马殷→马希声，不与陆希声同名合并；不建反向儿子重复。", "status": "draft", "id": "542116fa-fc89-54b5-b835-80bba1f4f698", "subject_id": "936f3e4e-e0b6-51b1-b686-6e6b8937d8f9", "source_id": "85e0f53d-9359-534d-9333-821db7c28b85"}, {"subject_table": "person", "field_path": "description", "claim_text": "新楚世家记马希声字若讷，为马殷次子。", "citation": "《新五代史》卷六十六，段落 xin-wudaishi-b08f244b9241-p003318；EPUB电子本，纸本及异文待核", "note": "原文：希聲字若訥，殷次子也。；核对说明：补字与次子身份，未由次子补推其他未明兄弟；新传后文高郁案留待主线下一批。", "status": "draft", "id": "ddded0c8-b15e-5bb1-94ae-66789d6f2b81", "subject_id": "5dca3ac0-5512-58ab-a330-ff34cb75ede8", "source_id": "1919904a-82f7-5285-87d4-0b49e3ae3ffd"}, {"subject_table": "event", "field_path": "description", "claim_text": "新楚世家记马殷建国时已以次子希声判内外诸军事。", "citation": "《新五代史》卷六十六，段落 xin-wudaishi-b08f244b9241-p003316；EPUB电子本，纸本及异文待核", "note": "原文：殷以潭州為長沙府，建國承制，自置官屬，以其弟賨為靜江軍節度使，子希振武順軍節度使，次子希聲判內外諸軍事，；核对说明：复用927楚建国出处，判军为此前职务背景，主929知政总军为本次委托，不强两段一定是同一次授官，也不重录927建国。", "status": "draft", "id": "17455979-d97d-53b5-95b5-91a894376408", "subject_id": "5c02d4f4-84ef-5733-acff-a66d703e353b", "source_id": "4c61cd0f-99af-58f0-ac6f-fcd5f9332130"}, {"subject_table": "event", "field_path": "description", "claim_text": "此后楚国政事先由马希声处理，才上报马殷。", "citation": "卷276·天成四年（929）·zztj-v276-y0929-p009·原文件第95行", "note": "原文：自是国政先历希声，乃闻于殷。；核对说明：自是叙述处理顺序的改变，不等马殷完全失权或不再知任何政事。", "status": "draft", "id": "fd14cd05-580e-50df-8123-01b06d87ce65", "subject_id": "3d1c9c78-dc33-57f5-9123-c5bc6efd6f26", "source_id": "85e0f53d-9359-534d-9333-821db7c28b85"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "929年三月本段；确日未载", "citation": "卷276·天成四年（929）·zztj-v276-y0929-p009·原文件第95行", "note": "原文：自是国政先历希声，乃闻于殷。；核对说明：按主书及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "6119b463-3b0c-5656-ba71-21a4b8da88ec", "subject_id": "3d1c9c78-dc33-57f5-9123-c5bc6efd6f26", "source_id": "85e0f53d-9359-534d-9333-821db7c28b85"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "马希声：先处理国政者。", "citation": "卷276·天成四年（929）·zztj-v276-y0929-p009·原文件第95行", "note": "原文：自是国政先历希声，乃闻于殷。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "ab38eebf-d4a3-5529-a8d2-d603a0ba2128", "subject_id": "da4a13ee-04be-5e8d-94b7-b4b7bd1ecdd6", "source_id": "85e0f53d-9359-534d-9333-821db7c28b85"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "马殷：听取其后报告者。", "citation": "卷276·天成四年（929）·zztj-v276-y0929-p009·原文件第95行", "note": "原文：自是国政先历希声，乃闻于殷。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "61c51154-07f8-57e3-b32c-b049913da138", "subject_id": "e70292fa-7d22-5b1f-9960-6dccd7486f96", "source_id": "85e0f53d-9359-534d-9333-821db7c28b85"}, {"subject_table": "event", "field_path": "description", "claim_text": "后唐禁铁锡钱。", "citation": "卷276·天成四年（929）·zztj-v276-y0929-p010·原文件第96行", "note": "原文：夏，四月，庚子朔，禁铁锡钱。；核对说明：币材禁令不扩大为废除所有钱币；旧铁鑞钱与主铁锡钱材字不同，保留异文不把鑞繁简成锡。", "status": "draft", "id": "57f5b271-0598-5db3-b37a-a297c42c41be", "subject_id": "214405a0-61ed-549f-aa92-27ec8d63a3ca", "source_id": "85e0f53d-9359-534d-9333-821db7c28b85"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "929年四月庚子朔", "citation": "卷276·天成四年（929）·zztj-v276-y0929-p010·原文件第96行", "note": "原文：夏，四月，庚子朔，禁铁锡钱。；核对说明：按主书及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "be185ace-838d-5422-aa07-7243e0cf4873", "subject_id": "214405a0-61ed-549f-aa92-27ec8d63a3ca", "source_id": "85e0f53d-9359-534d-9333-821db7c28b85"}, {"subject_table": "event", "field_path": "description", "claim_text": "旧明宗纪同月庚子朔记禁铁镴钱（底本作鑞）。", "citation": "《旧五代史》卷四十，段落 jiu-wudaishi-205deb4a7860-p001165；EPUB电子本，纸本及异文待核", "note": "原文：夏四月庚子朔，禁鐵鑞錢。；核对说明：鑞简体镴，非锡的繁体；标题循主铁锡，旧材字异说保留，不静默改原字。", "status": "draft", "id": "dfd9ce72-83fc-5ab5-a158-7ae8502d485d", "subject_id": "214405a0-61ed-549f-aa92-27ec8d63a3ca", "source_id": "7b8a4bad-e435-556f-baba-398c047e3a21"}, {"subject_table": "event", "field_path": "description", "claim_text": "当时湖南专用锡钱，铜钱一枚值锡钱百枚。", "citation": "卷276·天成四年（929）·zztj-v276-y0929-p010·原文件第96行", "note": "原文：时湖南专用锡钱，铜钱一直锡钱百，；核对说明：一直为价值相当之意；一比百是史载钱值，未转现代汇率、金属含量或币重；时背景无独始年，本文年条显示当时状态。", "status": "draft", "id": "058890c8-77d4-526b-a2e6-151d190a36cf", "subject_id": "1f7fc614-66b2-5c8b-b535-7d97e719d6e3", "source_id": "85e0f53d-9359-534d-9333-821db7c28b85"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "929年四月本段；确日未载", "citation": "卷276·天成四年（929）·zztj-v276-y0929-p010·原文件第96行", "note": "原文：时湖南专用锡钱，铜钱一直锡钱百，；核对说明：按主书及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "4c9309cb-ece5-52e4-b1dd-64963591b0b6", "subject_id": "1f7fc614-66b2-5c8b-b535-7d97e719d6e3", "source_id": "85e0f53d-9359-534d-9333-821db7c28b85"}, {"subject_table": "event", "field_path": "description", "claim_text": "湖南锡钱流入中原，禁法难以阻止。", "citation": "卷276·天成四年（929）·zztj-v276-y0929-p010·原文件第96行", "note": "原文：流入中国，法不能禁。；核对说明：中国按此时代文义作中原，不套现代国界或跨境法规；不能由法不能禁猜特定官员走私。", "status": "draft", "id": "ff45f22d-466b-5cba-ad40-ccf65f077231", "subject_id": "91dcc436-d86c-537f-af46-f8cb94441d52", "source_id": "85e0f53d-9359-534d-9333-821db7c28b85"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "929年四月本段；确日未载", "citation": "卷276·天成四年（929）·zztj-v276-y0929-p010·原文件第96行", "note": "原文：流入中国，法不能禁。；核对说明：按主书及对应补证纪时；追叙或他书记载另作说明，